head.script:
scwin.trigger1_onclick = function(e) {
    //var promise = ngmf.promise.dialog("20160504", "UI-1569-popup","",980,840,true,-1,-1,"");
    //debugger;
    WebSquare.uiplugin.popup.openPopup("calender_SKT-478_(WSQ-1093)_popup_auto.xml", {
        popupUrl: "sktUI-1569.xml", //팝업화면(부모)의 경로
        id: "popup", // id가 달라져야 팝업이 새창으로 뜹니다
        type: "window", //window, browser 중 하나  browser type의 경우 useIFrame 속성과 상관없이 window.open으로 열립니다.
        width: 400,
        height: 200,
        top: 100, //top과 left는 useIframe이 true인 경우 브라우져를 기준 false인 경우 모니터를 기준으로 한다.
        left: 100,
        popupName: "title", //popup 프레임의 표시줄에 나타납니다.
        modal: true, //modal을 이용해서 뒤 쪽 배경을 동작하지 않도록 만들기 위한 인자 입니다. false이면 뒤쪽의 컴퍼넌트가 사용 가능합니다.
        useIFrame: true, //true : IFrame 을 사용하는 WebSquare popup, false: window.open 을 사용하는 popup
        style: "", //popup의 스타일을 지정합니다. 값이 있으면 left top width height는 적용되지 않습니다.
        resizable: true,
        status: false,
        menubar: false,
        scrollbars: true,
        spa: true,
        title: false, //title,
        xml: "", //popup에 넘길 xmlDocument의 string popup창에서 WebSquare.uiplugin.popup.getPopupParam() api를 사용하여 가져올수 있습니다.
        srcData: "", //popup 객체의 type 이 window 일 때 Parent 에서 넘길 xpath
        destData: "" //popup 객체의 type 이 window 일 때 popup 에 설정할 xpath
    });
};
scwin.__isEl = function() {
    var el = WebSquare.wUnit.getDomById($p.id + "popup_iframe");
    return el1 = el.contentDocument;
}
scwin.getToday = function() {
    var date = new Date();
    dd = date.getDate() > 9 ? date.getDate() : '0' + date.getDate();
    mm = date.getMonth() > 8 ? date.getMonth() + 1 : '0' + (date.getMonth() + 1);
    yy = date.getFullYear();
    var today = yy + '-' + mm + '-' + dd;
    return today.toString();
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 버튼을 클릭한다.
    //1. After executing the sample file, click the button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify 1. 팝업화면이 보여진다.
    //1. A pop-up screen is displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#popup').length == 1", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#popup').css('display')", "block");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 캘린더를 클릭하고 날짜를 입력한다.
    //2. Click Calendar and enter the date.
    WebSquare.wUnit.addCommand("set", "scwin.__isEl().getElementById($p.id+'inputCalendar1_img').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#popup_iframe').contents().find('td.w2calendar_selected').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.__isEl().getElementById($p.id+'inputCalendar1_input').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 알림창에 'calendar'가 보여진다.
    //2. 'calendar' is displayed in the notification window.
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('showAlert')", "calendar");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "localStorage.removeItem('showAlert')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 알림창의 확인버튼을 클릭한다.
    //3. Click the OK button in the notification window.
    //Verify 3. 날짜가 입력된다.
    //3. The date is entered.
    WebSquare.wUnit.addCommand("assert", "scwin.__isEl().getElementById($p.id+'inputCalendar1_input').value == scwin.getToday()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. 팝업창을 닫는다.
    //4. Close the pop-up window.
    //bSquare.wUnit.addCommand("set", "popup_close.click()");
    WebSquare.wUnit.addCommand("set", "$p.closePopup('popup')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. 팝업창이 닫힌다.(이전에는 알림창이 1번더 발생함)
    //4. The pop-up window closes.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#popup').length", "0");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('showAlert')=='calendar'", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 09-Mar-2018
    //End unitTest
}
